import React, { useState } from 'react';
import { Play, Upload } from 'lucide-react';
import { Viewport } from '../../components/Viewport';
import { TerminalView } from '../../components/TerminalView';
import { LogEntry } from '../../types';

export const AnalysisView: React.FC = () => {
  const [logs] = useState<LogEntry[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-bold">Analysis Engine</h2>
          <p className="text-neutral-500 mt-1">Configure and initiate your processing pipeline.</p>
        </div>
        <button 
          onClick={() => setIsProcessing(!isProcessing)}
          className={`px-8 py-3 rounded-lg font-bold transition-all flex items-center gap-2 ${
            isProcessing ? 'bg-red-600 hover:bg-red-500' : 'bg-green-600 hover:bg-green-500'
          }`}
        >
          <Play className={`w-5 h-5 ${isProcessing ? 'fill-white' : ''}`} />
          {isProcessing ? 'STOP PIPELINE' : 'START ANALYSIS'}
        </button>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
        <Viewport title="Original Source" isLoading={isProcessing} />
        <Viewport title="Processed Result" isLoading={isProcessing} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2">
          <h3 className="text-sm font-bold uppercase tracking-widest text-neutral-500 mb-3 ml-1">Live Trace</h3>
          <TerminalView logs={logs} />
        </div>

        <div className="space-y-6">
          <div className="p-6 bg-neutral-900 border border-neutral-800 rounded-xl">
            <h3 className="text-lg font-medium mb-4 flex items-center gap-2">
              <Upload className="w-4 h-4 text-neutral-400" />
              Upload Source
            </h3>
            <div className="h-32 border-2 border-dashed border-neutral-800 rounded-lg flex flex-col items-center justify-center text-neutral-600 hover:border-neutral-700 hover:bg-neutral-800/50 cursor-pointer transition-all">
              <span className="text-xs">Drag and drop or click</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

