import { http, HttpResponse } from 'msw';
import { Project, AnalysisSession } from '../../types';

const MOCK_PROJECTS: Project[] = [
  {
    id: 'proj-1',
    name: 'Benagol',
    config: {
      training_path: 'dataset/training_images',
      color_correction: { reference_color_checker_path: 'default_cc.png' },
      geometrical_alignment: { marker_map: {}, output_size: [1000, 1000] },
      masking: { drawing_layers: { '1': 'layer1.png' } }
    }
  }
];

export const handlers = [
  // List Projects
  http.get('*/api/projects', () => {
    return HttpResponse.json(MOCK_PROJECTS);
  }),

  // Get Project Files
  http.get('*/api/projects/:projectId/files', ({ params }) => {
    return HttpResponse.json({
      config_files: [
        { key: 'ideal_checker', label: 'Ideal Reference Color Checker', rel_path: 'data/reference_images/global_TEOGRIM_reference.png', exists: true },
        { key: 'aruco_ref', label: 'ArUco Reference Image', rel_path: 'data/reference_images/global_aruco_reference.png', exists: true },
        { key: 'object_ref', label: 'Object Reference Image', rel_path: 'dataset/object_reference.png', exists: false },
      ],
      training_images: [
        { filename: 'sample_01.jpg', url: 'https://picsum.photos/id/10/800/600', thumbnail_url: 'https://picsum.photos/id/10/200/200' },
        { filename: 'sample_02.jpg', url: 'https://picsum.photos/id/11/800/600', thumbnail_url: 'https://picsum.photos/id/11/200/200' },
        { filename: 'sample_03.jpg', url: 'https://picsum.photos/id/12/800/600', thumbnail_url: 'https://picsum.photos/id/12/200/200' },
      ]
    });
  }),

  // Start Analysis
  http.post('*/api/analysis/run', async ({ request }) => {
    return HttpResponse.json({
      success: True,
      percentage: 98.5,
      matched_pixels: 1200000,
      total_pixels: 1218274,
      processed_image_url: '/output/Benagol/sample_result.png',
      debug_images: [
        {title: 'Color Mask', url: '/output/Benagol/mask.png'},
        {title: 'Contours', url: '/output/Benagol/contours.png'}
      ]
    });
  }),

  // Get Logs
  http.get('*/api/logs', () => {
    return HttpResponse.json([
      { timestamp: new Date().toISOString(), level: 'info', module: 'core', message: 'Pipeline initialized.' },
      { timestamp: new Date().toISOString(), level: 'info', module: 'cc', message: 'Detecting color checker...' },
    ]);
  }),
];

